      // =============== text ===============
      const vT = mkView('text');
      const subSeg = lib.segmented({ label: 'Text view', options: [['train', 'training example'], ['eval', 'evaluation example']], value: 'train', onchange: (v) => { const i = v === 'train' ? 0 : 1; apply(i); ctx.goStep(i); } });
      vT.appendChild(h('div', { class: 'controls' }, subSeg.el));
