      const trainBox = h('div', { class: 'dt-sub' }); vT.appendChild(trainBox);
      const docSel = h('select', { id: 'dt-doc', 'aria-label': 'Document' }, ...docs.map(d => h('option', { value: d.id }, `${d.id} · ${d.topic} · ${d.source_domain}`)));
